/**
 * Shop system — pricing, inventories, and services.
 *
 * Pricing from the RPGClassics reference data:
 *   Buy/sell ratio is roughly 105:60 (sell ≈ 57% of buy price).
 *   Enchanted items cost 2-10× base price.
 *   Cursed items are worthless (0 sell, shops won't buy).
 *   Broken items sell for 25cp at junk yard only.
 */
import { identifyItem, displayName } from '../data/items.ts';
import { ALL_EQUIPMENT_SPECS, specForItem, makeEquipmentItem, pickEquipmentIcon } from '../data/equipment.ts';
import { makeWeapon, randomWeaponName, addCoins, removeCoins, coinsIn, addToContainer, makePack, makeBelt, COIN_VALUE_CP } from '../data/items.ts';
import { townStockLevel } from '../data/progression.ts';
// ── Money helpers (purse + bank) ──────────────────────────────────────────────
/** Total value of a purse expressed in copper pieces. */
export function purseTotalCopper(purse) {
    if (!purse)
        return 0;
    return coinsIn(purse, 'copper')
        + coinsIn(purse, 'silver') * 10
        + coinsIn(purse, 'gold') * 100
        + coinsIn(purse, 'platinum') * 1000;
}
/**
 * Total balance across all bank lines of credit, in copper pieces.
 * Lines of credit are stored as cp-equivalent integers so no
 * denomination conversion is needed (per help topic 011, the bank
 * balance is shown in copper).
 */
export function bankTotalCopper(character) {
    if (!character.linesOfCredit)
        return 0;
    return Object.values(character.linesOfCredit).reduce((acc, n) => acc + n, 0);
}
/**
 * Deposit `amount` copper-equivalent from the player's purse into the
 * bank's line of credit.  Coins are drawn lowest-denomination-first.
 * Returns true if the deposit succeeded; false if the purse is empty
 * or doesn't have that much.
 */
export function bankDeposit(character, bankId, amount) {
    const purse = character.purse;
    if (!purse || amount <= 0)
        return false;
    if (purseTotalCopper(purse) < amount)
        return false;
    // Drain coins by value, smallest first; break a larger coin if needed
    let remaining = amount;
    for (const kind of ['copper', 'silver', 'gold', 'platinum']) {
        if (remaining <= 0)
            break;
        const value = COIN_VALUE_CP[kind];
        const have = coinsIn(purse, kind);
        const take = Math.min(have, Math.floor(remaining / value));
        if (take > 0) {
            removeCoins(purse, kind, take);
            remaining -= take * value;
        }
    }
    if (remaining > 0) {
        // Break a larger coin into copper change
        for (const kind of ['silver', 'gold', 'platinum']) {
            if (remaining <= 0)
                break;
            const value = COIN_VALUE_CP[kind];
            if (coinsIn(purse, kind) > 0 && value >= remaining) {
                removeCoins(purse, kind, 1);
                const change = value - remaining;
                if (change > 0)
                    addCoins(purse, 'copper', change);
                remaining = 0;
                break;
            }
        }
    }
    if (!character.linesOfCredit)
        character.linesOfCredit = {};
    character.linesOfCredit[bankId] = (character.linesOfCredit[bankId] ?? 0) + amount;
    return true;
}
/**
 * Withdraw `amount` copper-equivalent from the player's combined bank
 * balance.  Lines of credit are pooled across branches per help topic
 * "lines of credit transfer between the banks in the different towns".
 * Withdrawal hits the requested branch first, then falls back across
 * other branches.  Coins are added to the purse as copper for now;
 * the player can use the existing Consolidate Coins flow to split.
 */
export function bankWithdraw(character, bankId, amount) {
    if (!character.purse || amount <= 0)
        return false;
    if (bankTotalCopper(character) < amount)
        return false;
    if (!character.linesOfCredit)
        character.linesOfCredit = {};
    let remaining = amount;
    // Drain the requested branch first
    const here = character.linesOfCredit[bankId] ?? 0;
    const fromHere = Math.min(here, remaining);
    if (fromHere > 0) {
        character.linesOfCredit[bankId] = here - fromHere;
        remaining -= fromHere;
    }
    // Then drain any other branches
    for (const id of Object.keys(character.linesOfCredit)) {
        if (remaining <= 0)
            break;
        if (id === bankId)
            continue;
        const bal = character.linesOfCredit[id] ?? 0;
        const take = Math.min(bal, remaining);
        if (take > 0) {
            character.linesOfCredit[id] = bal - take;
            remaining -= take;
        }
    }
    addCoins(character.purse, 'copper', amount);
    return true;
}
// ── Pricing ───────────────────────────────────────────────────────────────────
/** Base prices by item kind (copper pieces) — fallback when no spec price exists. */
const BASE_PRICE = {
    weapon: 80,
    potion: 50,
    scroll: 40,
    container: 20,
    belt: 30,
    misc: 10,
};
/** Visit-based price variance: ±15% from base. Seed changes per visit. */
let visitSeed = Math.random();
export function resetVisitPrices() {
    visitSeed = Math.random();
}
function visitVariance() {
    // Deterministic-ish variance from the seed: 0.85 to 1.15
    return 0.85 + (visitSeed * 0.3);
}
/** Pack base prices by name. */
const PACK_PRICES = {
    'Small Pack': 50, 'Medium Pack': 150, 'Large Pack': 350,
    'Small Bag': 30, 'Medium Bag': 80, 'Large Bag': 180,
    'Small Pack of Holding': 5000, 'Medium Pack of Holding': 10000, 'Large Pack of Holding': 20000,
};
/** Get the buy price for an item (what the shop charges). */
export function buyPrice(item) {
    const spec = specForItem(item, ALL_EQUIPMENT_SPECS);
    let base;
    if (spec?.baseBuyPrice) {
        base = spec.baseBuyPrice;
    }
    else if (PACK_PRICES[item.name] !== undefined) {
        base = PACK_PRICES[item.name] ?? 50;
    }
    else {
        base = BASE_PRICE[item.kind] ?? 50;
    }
    // Enchantment multiplier
    if (item.enchantment > 0) {
        base = Math.floor(base * (2 + item.enchantment));
    }
    return Math.max(1, Math.floor(base * visitVariance()));
}
/** Get the sell price for an item (what the shop pays). */
export function sellPrice(item) {
    if (item.cursed && item.identified)
        return 0;
    if (item.broken)
        return 0;
    const spec = specForItem(item, ALL_EQUIPMENT_SPECS);
    if (spec?.baseSellPrice) {
        let base = spec.baseSellPrice;
        if (item.enchantment > 0)
            base = Math.floor(base * (2 + item.enchantment));
        return Math.max(1, Math.floor(base * visitVariance()));
    }
    return Math.floor(buyPrice(item) * 0.57);
}
/** Junk yard price: flat 25cp for anything, but never more than 25cp. */
export function junkYardPrice(item) {
    const normal = sellPrice(item);
    if (normal > 0 && normal < 25)
        return normal; // items worth less than 25cp sell at market price
    return 25;
}
