/**
 * Typed tile map system.
 *
 * Each tile is a structured object instead of a single ASCII character.
 * This eliminates context-dependent character interpretation and provides
 * a natural place for per-tile state (items, monsters) in the future.
 */
const TRAP_DAMAGE = {
    pit: { min: 2, max: 8 },
    arrow: { min: 3, max: 10 },
    dart: { min: 1, max: 4 },
    blade: { min: 4, max: 12 },
    acid: { min: 3, max: 10 },
    gas: { min: 2, max: 6 },
    teleport: { min: 0, max: 0 },
    deadfall: { min: 5, max: 15 },
    glyph: { min: 4, max: 14 },
    trapdoor: { min: 2, max: 8 },
};
const TRAP_ICONS = {
    pit: '/assets/sprites/icons/Traps/pit.png',
    arrow: '/assets/sprites/icons/Traps/arrow.png',
    dart: '/assets/sprites/icons/Traps/dart.png',
    blade: '/assets/sprites/icons/Traps/blade.png',
    acid: '/assets/sprites/icons/Traps/acid.png',
    gas: '/assets/sprites/icons/Traps/gas.png',
    teleport: '/assets/sprites/icons/Traps/teleport.png',
    deadfall: '/assets/sprites/icons/Traps/deadfall.png',
    glyph: '/assets/sprites/icons/Traps/glyph.png',
    trapdoor: '/assets/sprites/icons/Traps/trapdoor.png',
};
/** Get the icon for a trap (only shown when detected). */
export function trapIcon(kind) {
    return TRAP_ICONS[kind];
}
/** Roll trap damage. Returns 0 for non-damaging traps. */
export function rollTrapDamage(kind) {
    const { min, max } = TRAP_DAMAGE[kind];
    if (max === 0)
        return 0;
    return min + Math.floor(Math.random() * (max - min + 1));
}
/** All trap kinds for random selection. */
export const ALL_TRAP_KINDS = [
    'pit', 'arrow', 'dart', 'blade', 'acid', 'gas', 'teleport', 'deadfall', 'glyph', 'trapdoor',
];
// ── Accessors ─────────────────────────────────────────────────────────────────
const VOID_TILE = { terrain: 'void', walkable: false, items: [] };
export function getTileAt(map, x, y) {
    if (y < 0 || y >= map.height)
        return VOID_TILE;
    const row = map.tiles[y];
    if (!row || x < 0 || x >= map.width)
        return VOID_TILE;
    return row[x] ?? VOID_TILE;
}
export function isWalkable(map, x, y) {
    return getTileAt(map, x, y).walkable;
}
export function exitAt(map, x, y) {
    return getTileAt(map, x, y).exit;
}
export function buildingAt(map, x, y) {
    return getTileAt(map, x, y).building;
}
// ── Ground item operations ────────────────────────────────────────────────────
/** Drop an item onto a tile. */
export function dropItem(map, x, y, item) {
    const tile = getTileAt(map, x, y);
    if (tile === VOID_TILE)
        return;
    tile.items.push(item);
}
/** Pick up an item from a tile by id. Returns the item, or undefined. */
export function pickupItem(map, x, y, itemId) {
    const tile = getTileAt(map, x, y);
    const idx = tile.items.findIndex((i) => i.id === itemId);
    if (idx === -1)
        return undefined;
    return tile.items.splice(idx, 1)[0];
}
/** Pick up all items from a tile. Returns the items array (now empty on tile). */
export function pickupAllItems(map, x, y) {
    const tile = getTileAt(map, x, y);
    const items = [...tile.items];
    tile.items.length = 0;
    return items;
}
// ── Fog of war ────────────────────────────────────────────────────────────────
/**
 * Reveal tiles visible from (px, py) using simple raycasting.
 * When the player is standing in a room, also reveals the entire room.
 * Walls block vision but are themselves revealed.
 */
export function revealAround(map, px, py, radius = 10) {
    // If player is in a room, reveal the entire room + its walls
    const playerTile = getTileAt(map, px, py);
    if (playerTile.roomId !== undefined) {
        if (!(map.revealedRooms instanceof Set))
            map.revealedRooms = new Set();
        revealRoom(map, playerTile.roomId);
        map.revealedRooms.add(playerTile.roomId);
    }
    // Normal LOS reveal for corridors and nearby area
    for (let dy = -radius; dy <= radius; dy++) {
        for (let dx = -radius; dx <= radius; dx++) {
            if (dx * dx + dy * dy > radius * radius)
                continue;
            const tx = px + dx, ty = py + dy;
            if (ty < 0 || ty >= map.height || tx < 0 || tx >= map.width)
                continue;
            if (hasLineOfSight(map, px, py, tx, ty)) {
                const tile = map.tiles[ty]?.[tx];
                if (tile)
                    tile.explored = true;
            }
        }
    }
}
/** Reveal all tiles in a room plus adjacent walls. */
function revealRoom(map, roomId) {
    for (let y = 0; y < map.height; y++) {
        for (let x = 0; x < map.width; x++) {
            const tile = map.tiles[y]?.[x];
            if (!tile)
                continue;
            if (tile.roomId === roomId) {
                tile.explored = true;
                // Also reveal adjacent walls
                for (let dy = -1; dy <= 1; dy++) {
                    for (let dx = -1; dx <= 1; dx++) {
                        const adj = map.tiles[y + dy]?.[x + dx];
                        if (adj && adj.feature === 'wall')
                            adj.explored = true;
                    }
                }
            }
        }
    }
}
export function hasLineOfSight(map, x0, y0, x1, y1) {
    // Bresenham's line — stop if we hit a non-walkable tile (but mark it visible)
    let x = x0, y = y0;
    const dx = Math.abs(x1 - x0), dy = Math.abs(y1 - y0);
    const sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1;
    let err = dx - dy;
    for (;;) {
        if (x === x1 && y === y1)
            return true;
        const tile = map.tiles[y]?.[x];
        // Walls and void block vision but are themselves visible
        if (tile && !tile.walkable && !(x === x0 && y === y0))
            return x === x1 && y === y1;
        const e2 = 2 * err;
        if (e2 > -dy) {
            err -= dy;
            x += sx;
        }
        if (e2 < dx) {
            err += dx;
            y += sy;
        }
    }
}
